/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: Media, mount
 * Tests
 *   - the Files section identifies its own task and leaves publication actions in Publish
 *   - a completed publication links confirmed catalog identities without reopening or publishing the historical import
 *   - reselection mismatches never dispatch, and a matched file waits for the explicit Resume approval
 *   - 202 publication admission is not completion and source cleanup remains possible after confirmed publication
 *   - embedded artwork requires explicit selection and unavailable upload never dispatches
 *   - another current administrator retries staging cleanup with the original operation and revision
 *   - cancelling publication confirms the project and captures its current revision and original approval
 *   - cancelled cleanup uses the original approval and blocks media changes until exact cleanup is confirmed
 *   - a completed publication cannot be cancelled
 *   - an exhausted publication allowance explains availability while staged cleanup remains usable
 *   - embedded artwork removal confirms its own slot without selecting that cover
 *   - publication confirmation keeps its reviewed name and revision until the administrator explicitly reopens it
 *   - removal cannot adopt a replacement asset or its recovery intent while its dialog is open
 *   - choosing a manual cover queues it without a dialog, and it waits for no draft or revision
 *   - a second slot keeps its own row status while the first is retried only by its starter
 *   - a failed upload asks for its file again, and Retry upload explicitly queues the reselected copy for any administrator
 *   - removing a staged file forgets its chosen copy and queued retry, so a later Resume never sends it again
 * @end-catalog */

import type { ComponentProps } from 'react';
import { act, cleanup, fireEvent, render, screen, within } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { MemoryRouter } from 'react-router';
import { captureAccountOperation } from '../../api/accountEpoch';
import { adminWorkspace } from './adminWorkspace';
import { ImportMedia } from './ImportMedia';
import { AdminMutation } from './useAdminMutation';
import { importUploadQueue } from './importUploadQueue';
import { loadImportUploadQueue, useImportUploadQueue } from './useImportUploadQueue';
import { detail, session, slotId, slotTwo, viewer } from './adminFixtures.testSupport';
/** Subscribes the panel to its import's queue as the import page does. */
function Media(props: Omit<ComponentProps<typeof ImportMedia>, 'uploads'>) { return <ImportMedia {...props} uploads={useImportUploadQueue(props.item.id)} />; }
function mount(item = detail(), operation = new AdminMutation(), view?: 'files' | 'publication') { const client = new QueryClient(); client.setQueryData(['browser-session'], session); const element = (value: typeof item) => <QueryClientProvider client={client}><MemoryRouter><Media item={value} operation={operation} disabled={false} view={view} /></MemoryRouter></QueryClientProvider>; return { ...render(element(item)), element, operation }; }
// With the engine loaded, a panel opens its queue on mount; useImportUploadQueue.test covers the first load.
beforeAll(() => loadImportUploadQueue());
beforeEach(() => { adminWorkspace.reset(); adminWorkspace.authorize(captureAccountOperation(viewer), true, true); adminWorkspace.select('admin'); });
afterEach(() => { cleanup(); adminWorkspace.reset(); vi.unstubAllGlobals(); });
test('the Files section identifies its own task and leaves publication actions in Publish', () => {
  const item = detail(); item.publication = 'notStarted'; item.capabilities.publish = true;
  mount(item, new AdminMutation(), 'files');
  expect(screen.getByRole('heading', { name: 'Files' })).toBeVisible();
  // One manual cover picker remains; audio rows have no per-file inputs, only shared reselection controls.
  expect(screen.queryByLabelText('Select original file')).not.toBeInTheDocument();
  expect(screen.getAllByLabelText('Choose Album cover')).toHaveLength(1);
  expect(document.querySelectorAll('input[type=file]')).toHaveLength(3);
  expect(document.querySelectorAll('input[type=file]')[2]).toBe(screen.getByLabelText('Choose Album cover'));
  expect(screen.getByRole('button', { name: 'Reselect folder' })).toBeVisible(); expect(screen.getByRole('button', { name: 'Reselect files' })).toBeVisible();
  expect(screen.queryByRole('button', { name: 'Publish Album' })).not.toBeInTheDocument();
});
test('a completed publication links confirmed catalog identities without reopening or publishing the historical import', () => {
  const item = detail(); item.publication = 'complete'; item.capabilities.publish = true;
  item.published = { albumId: '111111111111111111111111', artistId: '222222222222222222222222', trackIds: [] };
  const operation = new AdminMutation(), run = vi.spyOn(operation, 'run').mockImplementation(() => {});
  mount(item, operation, 'publication');
  expect(screen.getByRole('link', { name: 'Edit published Album' })).toHaveAttribute('href', '/admin/catalog/album/111111111111111111111111');
  expect(screen.getByRole('link', { name: 'Edit Artist' })).toHaveAttribute('href', '/admin/catalog/artist/222222222222222222222222');
  expect(screen.queryByRole('button', { name: 'Publish Album' })).not.toBeInTheDocument();
  expect(run).not.toHaveBeenCalled();
});
