test('removing a staged file forgets its chosen copy and queued retry, so a later Resume never sends it again', () => {
  const item = detail(); item.publication = 'notStarted'; item.capabilities.upload = true;
  item.assets = [{ slotId: 'cover', state: 'ready', byteLength: 5, sha256: 'c'.repeat(64), contentType: 'image/png', tags: null, recovery: { operationId: '30000000-0000-4000-8000-000000000003', expectedRevision: 1, kind: 'upload', startedByMe: true } }];
  const cover = new File(['cover'], 'cover.png', { type: 'image/png' }), audio = new File(['a'.repeat(100)], '01 First.mp3');
  adminWorkspace.retain(`files:${item.id}`, { cover, [slotId]: audio }, adminWorkspace.capture());
  const operation = new AdminMutation(), remove = vi.spyOn(operation, 'cleanup').mockImplementation(() => {}), discard = vi.spyOn(importUploadQueue(item.id), 'discard');
  mount(item, operation);
  const row = screen.getAllByText('Manually selected cover').map(label => label.closest('li')).find(Boolean)!;
  fireEvent.click(within(row).getByRole('button', { name: 'Remove file' }));
  fireEvent.click(within(screen.getByRole('dialog')).getByRole('button', { name: 'Remove file' }));
  expect(remove).toHaveBeenCalledWith(`/${item.id}/assets/cover`, item.revision, undefined); expect(discard).toHaveBeenCalledWith('cover');
  expect(adminWorkspace.buffer<Record<string, File>>(`files:${item.id}`)).toEqual({ [slotId]: audio });
});
